/**
 * `?api=mock`: a PrimersClient that replays design fixtures (real Primer3
 * 2.6.1 output on sorghum_bicolor, generated by
 * test/components/fixtures/build-designs.mjs) and simulates check jobs
 * (queued → running with partial results → done). Check results are
 * synthetic, except the P2/P3 off-targets and the J_L + P1_R transcriptome
 * groups, which follow the spec examples.
 */
import {
  CHECK_DEFAULTS,
  cdnaToGenomicBlocks,
  hashString,
  pairKey,
  PANGENOME_TRANSCRIPT_MODELS_ONLY,
  pollCheckJob,
  PrimersApiError,
  revcomp,
  summarizePangenome,
  transcriptLayout,
  type CheckJob,
  type CheckRequest,
  type CheckResults,
  type DesignRequest,
  type DesignResponse,
  type GenomeEntry,
  type GenomesResponse,
  type GrameneGene,
  type OffTarget,
  type PangenomeGenomeResult,
  type PangenomeStatus,
  type PollOptions,
  type PrimerOligo,
  type PrimerPair,
  type PrimersClient,
  type RequestOptions,
  type SpecificityPairResult,
  type TranscriptomePairResult,
} from 'gramene-primers';
import gene200Json from '../../test/fixtures/genes/SORBI_3001G000200.json';
import gene700Json from '../../test/fixtures/genes/SORBI_3001G000700.json';
import gene46200Json from '../../test/fixtures/genes/SORBI_3001G046200.json';
import gene87700Json from '../../test/fixtures/genes/SORBI_3004G087700.json';
import gene87700Seq from '../../test/fixtures/sequences/SORBI_3004G087700.gene.txt?raw';
import gene200Design from '../../test/components/fixtures/designs/gene-SORBI_3001G000200-flanks.json';
import gene700Design from '../../test/components/fixtures/designs/gene-SORBI_3001G000700.json';
import noPairsDesign from '../../test/components/fixtures/designs/no-pairs-SORBI_3001G000200.json';
import regionDesign from '../../test/components/fixtures/designs/region-1-11080-15099-minus.json';
import sequenceDesign from '../../test/components/fixtures/designs/sequence-iupac.json';
import tx200Design from '../../test/components/fixtures/designs/transcript-SORBI_3001G000200.json';
import tx46200a from '../../test/components/fixtures/designs/transcript-SORBI_3001G046200.1.json';
import tx46200b from '../../test/components/fixtures/designs/transcript-SORBI_3001G046200.2.json';
import tx87700Design from '../../test/components/fixtures/designs/transcript-SORBI_3004G087700.3.json';
import type { MockVariant } from './pages';

export const GENES: Readonly<Record<string, GrameneGene>> = Object.freeze({
  SORBI_3001G000200: gene200Json as unknown as GrameneGene,
  SORBI_3001G000700: gene700Json as unknown as GrameneGene,
  SORBI_3001G046200: gene46200Json as unknown as GrameneGene,
  SORBI_3004G087700: gene87700Json as unknown as GrameneGene,
});

export const SEQS = Object.freeze({
  P1_L: 'GATCGACAATCCGACGATAGAAG',
  P1_R: 'GTGAACATCATGCTGCCCGATG',
  P2_L: 'GGACAGCTCCACAACATATCAG',
  P2_R: 'GGACATTTGAAGCCCATGGCC',
  P3_L: 'GATATCAGTGGAATCATAAGACCG',
  P3_R: 'CATCGATATCAGGATCTGGCTT',
  P5_L: 'CGACGAGGAGGCGCTGCGATG',
  J_L: 'CCAACAAAGTCATGGATGCACT',
});

export interface MockClientOptions {
  variant?: MockVariant;
  /** Multiplies every simulated latency (tests use a small value). */
  delayScale?: number;
  /** Simulate an API error code on the first design or check request. */
  failWith?: string | null;
  /** Skip the queued phase of check jobs. */
  skipQueue?: boolean;
}

const clone = <T,>(v: T): T => JSON.parse(JSON.stringify(v)) as T;

function abortError(): Error {
  return new DOMException('The operation was aborted.', 'AbortError');
}

function wait(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(abortError());
    const t = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(t);
      reject(abortError());
    };
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

function gc(seq: string): number {
  return Math.round(((seq.match(/[GC]/g)?.length ?? 0) / seq.length) * 10000) / 100;
}

/** Rough salt-adjusted Tm, for mock pairs only. */
function roughTm(seq: string): number {
  const g = (seq.match(/[GC]/g)?.length ?? 0);
  return Math.round((64.9 + (41 * (g - 16.4)) / seq.length) * 100) / 100;
}

function oligo(seq: string, start: number, end: number, extra: Partial<PrimerOligo> = {}): PrimerOligo {
  return { seq, start, end, len: seq.length, tm: roughTm(seq), gc: gc(seq), self_any_th: 0, self_end_th: 0, hairpin_th: 0, end_stability: 3.5, penalty: 0.4, junction: null, genomic: null, ...extra };
}

/** Gene-mode template on SORBI_3004G087700 (+, flanks 0) with the spec P1/P2/P3 pairs. */
function verifiedGenePairsDesign(): DesignResponse {
  const gene = GENES.SORBI_3004G087700!;
  const seq = gene87700Seq.trim();
  const g0 = gene.location.start;
  const pair = (rank: number, left: string, right: string, gStart: number, gEnd: number): PrimerPair => {
    const ls = gStart - g0 + 1;
    const re = gEnd - g0 + 1;
    const rs = re - right.length + 1;
    return {
      rank,
      penalty: 0.3 + rank / 10,
      product_size: re - ls + 1,
      product_tm: 82.5,
      compl_any_th: 0,
      compl_end_th: 0,
      left: oligo(left, ls, ls + left.length - 1, { genomic: { region: '4', start: gStart, end: gStart + left.length - 1, strand: 1, blocks: [{ start: gStart, end: gStart + left.length - 1 }] } }),
      right: oligo(right, rs, re, { genomic: { region: '4', start: gEnd - right.length + 1, end: gEnd, strand: -1, blocks: [{ start: gEnd - right.length + 1, end: gEnd }] } }),
      product: { start: ls, end: re, genomic: { region: '4', start: gStart, end: gEnd, strand: 1 } },
    };
  };
  const layout = transcriptLayout(gene, 'SORBI_3004G087700.3')!;
  return {
    template: {
      mode: 'gene',
      system_name: 'sorghum_bicolor',
      gene_id: gene._id,
      transcript_id: layout.transcriptId,
      region: '4',
      start: gene.location.start,
      end: gene.location.end,
      strand: 1,
      length: seq.length,
      seq,
      masked: false,
      mask_source: null,
      mask: [],
      masked_fraction: 0,
      features: {
        gene: { start: 1, end: seq.length },
        exons: layout.segments.map((s) => ({ id: s.exonId, start: s.gStart - g0 + 1, end: s.gEnd - g0 + 1, genomic: { start: s.gStart, end: s.gEnd } })),
        cds: null,
        junctions: [],
      },
    },
    pairs: [pair(0, SEQS.P1_L, SEQS.P1_R, 7422190, 7422843), pair(1, SEQS.P2_L, SEQS.P2_R, 7423537, 7423746), pair(2, SEQS.P3_L, SEQS.P3_R, 7422482, 7423061)],
    explain: { left: { raw: 'mock', considered: 3, ok: 3 }, right: { raw: 'mock', considered: 3, ok: 3 }, pair: { raw: 'mock', considered: 3, ok: 3 } },
    settings: { preset: 'pcr', junction_spanning: false, avoid_repeats: false, repeat_mask_mode: null, params: {} },
    engine: { primer3: '2.6.1 (mock replay)' },
    warnings: [],
  };
}

/** Transcript-mode design on SORBI_3004G087700.3 with J_L (spans junction 743) + P1_R, 278 bp. */
function verifiedQpcrDesign(): DesignResponse {
  const gene = GENES.SORBI_3004G087700!;
  const layout = transcriptLayout(gene, 'SORBI_3004G087700.3')!;
  const lb = cdnaToGenomicBlocks(layout, 730, 751);
  const rb = cdnaToGenomicBlocks(layout, 986, 1007);
  const env = (b: { start: number; end: number }[]) => ({ start: b[0]!.start, end: b[b.length - 1]!.end });
  const all = [...lb, ...rb].sort((a, b) => a.start - b.start);
  const product = env(all);
  const res = clone(tx87700Design.response) as unknown as DesignResponse;
  res.pairs = [
    {
      rank: 0,
      penalty: 0.52,
      product_size: 278,
      product_tm: 83.1,
      compl_any_th: 0,
      compl_end_th: 0,
      left: oligo(SEQS.J_L, 730, 751, { junction: { position: 743, overlap_5p: 14, overlap_3p: 8 }, genomic: { region: '4', ...env(lb), strand: 1, blocks: lb } }),
      right: oligo(SEQS.P1_R, 986, 1007, { genomic: { region: '4', ...env(rb), strand: -1, blocks: rb } }),
      product: { start: 730, end: 1007, genomic: { region: '4', ...product, strand: 1 }, genomic_size: product.end - product.start + 1 },
    },
  ];
  res.engine = { primer3: '2.6.1 (mock replay)' };
  return res;
}

/** Sequence-mode design: P5_L + 180 nt of SORBI_3004G087700 + reverse complement of P2_R. */
function repetitiveP5lDesign(): DesignResponse {
  const middle = gene87700Seq.trim().slice(3000, 3180);
  const seq = `${SEQS.P5_L}${middle}${revcomp(SEQS.P2_R)}`;
  const end = seq.length;
  return {
    template: { mode: 'sequence', system_name: 'sorghum_bicolor', gene_id: null, transcript_id: null, region: null, start: null, end: null, strand: null, length: end, seq, masked: false, mask_source: null, mask: [], masked_fraction: 0, features: {} },
    pairs: [
      {
        rank: 0,
        penalty: 1.2,
        product_size: end,
        product_tm: null,
        compl_any_th: 0,
        compl_end_th: 0,
        left: oligo(SEQS.P5_L, 1, SEQS.P5_L.length),
        right: oligo(SEQS.P2_R, end - SEQS.P2_R.length + 1, end),
        product: { start: 1, end, genomic: null },
      },
    ],
    explain: null,
    settings: { preset: 'pcr', junction_spanning: false, avoid_repeats: false, repeat_mask_mode: null, params: {} },
    engine: { primer3: '2.6.1 (mock replay)' },
    warnings: [],
  };
}

function fixtureFor(req: DesignRequest, variant: MockVariant): DesignResponse | PrimersApiError {
  const pick = (f: { response: unknown }) => clone(f.response) as DesignResponse;
  if (variant === 'verified-gene-pairs' && req.mode === 'gene') return verifiedGenePairsDesign();
  if (variant === 'verified-qpcr-pair' && req.mode === 'transcript') return verifiedQpcrDesign();
  if (variant === 'repetitive-p5l' && req.mode === 'sequence') return repetitiveP5lDesign();
  switch (req.mode) {
    case 'gene':
      if (req.gene_id === 'SORBI_3001G000200') return pick(gene200Design);
      if (req.gene_id === 'SORBI_3001G000700') return pick(gene700Design);
      if (req.gene_id === 'SORBI_3004G087700') return verifiedGenePairsDesign();
      break;
    case 'transcript': {
      const ranges = req.params?.product_size_ranges;
      if (req.gene_id === 'SORBI_3001G000200') return ranges && ranges.every((r) => r[1] < 80) ? pick(noPairsDesign) : pick(tx200Design);
      if (req.gene_id === 'SORBI_3001G046200') return req.transcript_id === 'SORBI_3001G046200.1' ? pick(tx46200a) : pick(tx46200b);
      if (req.gene_id === 'SORBI_3004G087700') return pick(tx87700Design);
      break;
    }
    case 'region':
      return pick(regionDesign);
    case 'sequence':
      return pick(sequenceDesign);
  }
  return new PrimersApiError({ status: 404, code: 'UNKNOWN_GENE', message: `The mock API has no fixture for ${req.gene_id ?? req.mode}` });
}

/** Adds an illustrative repeat mask when `avoid_repeats` is set. */
function applyMockMask(res: DesignResponse, req: DesignRequest): DesignResponse {
  if (!req.avoid_repeats) return res;
  const L = res.template.length;
  const runs: [number, number][] = [];
  for (let s = Math.floor(L * 0.12); s < L; s += Math.floor(L * 0.27)) runs.push([s, Math.max(20, Math.floor(L * 0.06))]);
  const source = res.template.mode === 'sequence' ? 'user_lowercase' : res.template.system_name === 'sorghum_rio' ? 'softmask' : 'blast_depth';
  res.template = { ...res.template, masked: true, mask_source: source, mask: runs, masked_fraction: runs.reduce((a, r) => a + r[1], 0) / L };
  if (source === 'blast_depth') res.warnings = [...res.warnings, { code: 'BLAST_DEPTH_MASK', message: 'Repeats estimated by BLAST copy number (mock); multi-copy gene families are masked too' }];
  return res;
}

